namespace Doroti.Framework.Material;

public class PlatformAdaptiveIcons : Icons
{
    public PlatformAdaptiveIcons()
    {
    }

    internal static bool _isCupertino()
    {
        switch (PlatformLibrary.defaultTargetPlatform)
        {
            case TargetPlatform.android:
            case TargetPlatform.fuchsia:
            case TargetPlatform.linux:
            case TargetPlatform.windows:
                {
                    return false;
                }
            case TargetPlatform.iOS:
            case TargetPlatform.macOS:
                {
                    return true;
                }
            default:
                throw new InvalidOperationException("Non-exhaustive Dart switch value.");
        }
        throw new InvalidOperationException("Dart control flow completed without a value.");
    }

    public new virtual IconData arrow_back => !_isCupertino() ? Icons.arrow_back : arrow_back_ios;
    public new virtual IconData arrow_back_outlined => !_isCupertino() ? Icons.arrow_back_outlined : arrow_back_ios_outlined;
    public new virtual IconData arrow_back_rounded => !_isCupertino() ? Icons.arrow_back_rounded : arrow_back_ios_rounded;
    public new virtual IconData arrow_back_sharp => !_isCupertino() ? Icons.arrow_back_sharp : arrow_back_ios_sharp;
    public new virtual IconData arrow_forward => !_isCupertino() ? Icons.arrow_forward : arrow_forward_ios;
